import 'server-only';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { Zap } from 'lucide-react';
import { CoverageClient } from './_components/CoverageClient';
import { mergeByMetro } from './lib/mergeByMetro';
import type { CoverageData } from './lib/types';

// data.json is generated by scripts/robotaxi-charging-analysis.ts and checked in
// (see docs/robotaxi-charging-coverage) — read directly rather than duplicating
// the AFDC/av-map-data fetch on every page load. Re-run
// ./scripts/build-charging-report.sh to refresh it.
async function getCoverageData(): Promise<CoverageData | null> {
  try {
    const file = path.join(process.cwd(), 'docs/robotaxi-charging-coverage/data.json');
    return JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    console.error('[charging-coverage] failed to load data.json:', err);
    return null;
  }
}

export default async function ChargingCoveragePage() {
  const data = await getCoverageData();

  return (
    <div className="w-full">
      <div className="mb-6">
        <div className="flex items-center gap-2 mb-2">
          <Zap className="h-3.5 w-3.5 text-[#1a3a7a]" />
          <span className="font-mono text-[10px] font-semibold uppercase tracking-[.16em] text-[#0e1c36]/40">
            Site Selection
          </span>
        </div>
        <h1 className="text-2xl font-bold text-[#0e1c36]">Robotaxi Charging Coverage</h1>
        <p className="text-sm text-[#0e1c36]/50 mt-1 max-w-2xl">
          Every active US robotaxi service-area boundary overlaid with NREL AFDC public DC-fast
          charging data — per-operator footprint, growth vs. charging density, network
          dependency, and cross-fleet overlap converted to a vehicle-charge-session ceiling.
        </p>
      </div>

      {data ? (
        <CoverageClient data={data} metros={mergeByMetro(data.perArea, data.meta.fastTierKw, data.meta.capacityAssumptions.sessionsPerPortPerDay)} />
      ) : (
        <div className="rounded-md border border-[#0e1c36]/12 bg-white p-6 text-sm text-[#0e1c36]/60">
          Couldn&apos;t load <code className="bg-[#0e1c36]/5 px-1 rounded">docs/robotaxi-charging-coverage/data.json</code>.
          Run <code className="bg-[#0e1c36]/5 px-1 rounded">./scripts/build-charging-report.sh</code> to generate it.
        </div>
      )}
    </div>
  );
}
